def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    sorted_nums = sorted(nums)
    sorted_unique = []
    prev = None
    for num in sorted_nums:
        if num != prev:
            sorted_unique.append(num)
            prev = num

    groups = []
    current_start = sorted_unique[0]
    current_end = sorted_unique[0]

    for i in range(1, len(sorted_unique)):
        num = sorted_unique[i]
        if num == current_end + 1:
            current_end = num
        else:
            groups.append((current_start, current_end))
            current_start = num
            current_end = num

    groups.append((current_start, current_end))

    parts = []
    for start, end in groups:
        if end - start >= 2:
            parts.append(f"{start}..{end}")
        else:
            for num in range(start, end + 1):
                parts.append(str(num))

    return ','.join(parts)
